import { useState } from 'react';
import {
  Screen,
  Card,
  Stack,
  Row,
  TextField,
  Button,
  Badge,
  Alert,
  KeyBar,
  EmptyState,
} from '@nexti/ds';

type Msg = { tone: 'info' | 'success' | 'warning' | 'error'; text: string } | null;

const MENU = [
  { value: '1', label: 'Pagar una orden' },
  { value: '2', label: 'Consultar una orden' },
];

export default function PagoMenu({ navigate }: { navigate: (to: string) => void }) {
  const [opcion, setOpcion] = useState('');
  const [mensaje, setMensaje] = useState<Msg>(null);
  const [exited, setExited] = useState(false);

  // Sample output value, format 99/99/99
  const fecha = '15/03/25';

  const readValue = (v: unknown): string =>
    typeof v === 'string' ? v : (v as { target?: { value?: string } })?.target?.value ?? '';

  const handleChange = (v: unknown) => {
    // Numeric field, maximum length 1
    const clean = readValue(v).replace(/\D/g, '').slice(0, 1);
    setOpcion(clean);
    if (mensaje) setMensaje(null);
  };

  const error =
    mensaje?.tone === 'error' ? mensaje.text : undefined;

  const onEnter = () => {
    if (opcion === '') {
      setMensaje({ tone: 'error', text: 'Debe ingresar una opción.' });
      return;
    }
    if (opcion !== '1' && opcion !== '2') {
      setMensaje({ tone: 'error', text: 'Opción inválida. Ingrese 1 o 2.' });
      return;
    }
    setMensaje({ tone: 'success', text: 'Opción aceptada. Continuando...' });
    // The spec defines no outgoing navigation; both options are assumed to open the order screen.
    navigate('SCR-PAGOORD');
  };

  const onExit = () => {
    setExited(true);
    setMensaje({ tone: 'info', text: 'Sesión de pagos finalizada.' });
  };

  const onKeyDown = (e: { key: string; preventDefault: () => void }) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      onEnter();
    } else if (e.key === 'F3') {
      e.preventDefault();
      onExit();
    }
  };

  const keyBar = (
    <KeyBar
      actions={[
        { key: 'ENTER', label: 'Continuar', onPress: onEnter, primary: true },
        { key: 'PF3', label: 'Salir', onPress: onExit },
      ]}
    />
  );

  if (exited) {
    return (
      <Screen title="Banco ficticio - Pagos" code="PAGOMEN" keys={keyBar}>
        <Stack>
          <div data-field="MENSAJE">
            {mensaje && <Alert tone={mensaje.tone}>{mensaje.text}</Alert>}
          </div>
          <EmptyState />
          <Row>
            <Button
              variant="primary"
              onClick={() => {
                setExited(false);
                setOpcion('');
                setMensaje(null);
              }}
            >
              Volver al menú
            </Button>
          </Row>
        </Stack>
      </Screen>
    );
  }

  return (
    <Screen title="Banco ficticio - Pagos" code="PAGOMEN" keys={keyBar}>
      <div onKeyDown={onKeyDown}>
        <Stack>
          <Row>
            <span>Fecha:</span>
            <div data-field="FECHA">
              <strong>{fecha}</strong>
            </div>
          </Row>

          <Card title="Menú de pagos">
            <Stack>
              {MENU.map((item) => (
                <Row key={item.value}>
                  <Badge>{item.value}</Badge>
                  <span>{item.label}</span>
                  <Button variant="ghost" onClick={() => { setOpcion(item.value); setMensaje(null); }}>
                    Seleccionar
                  </Button>
                </Row>
              ))}
            </Stack>
          </Card>

          <Card
            title="Selección"
            actions={
              <Row>
                <Button variant="primary" shortcut="ENTER" onClick={onEnter}>
                  Continuar
                </Button>
                <Button variant="secondary" shortcut="PF3" onClick={onExit}>
                  Salir
                </Button>
              </Row>
            }
          >
            <div data-field="OPCION">
              <TextField
                label="Opción"
                required
                numeric
                maxLength={1}
                hint="Ingrese 1 para pagar una orden o 2 para consultarla"
                error={error}
                value={opcion}
                onChange={handleChange}
              />
            </div>
          </Card>

          <div data-field="MENSAJE" aria-live="polite">
            {mensaje && <Alert tone={mensaje.tone}>{mensaje.text}</Alert>}
          </div>
        </Stack>
      </div>
    </Screen>
  );
}
