import { useState } from 'react'
import { Screen, Card, Stack, TextField, Button, Alert } from '@nexti/ds'
import type { ScreenProps } from './types'

type Msg = { tone: 'info' | 'success' | 'warning' | 'error'; text: string } | null

const MENU = [
  { value: '1', label: 'Pagar una orden' },
  { value: '2', label: 'Consultar una orden' },
]

function today(): string {
  const d = new Date()
  const p = (n: number) => String(n).padStart(2, '0')
  return `${p(d.getDate())}/${p(d.getMonth() + 1)}/${p(d.getFullYear() % 100)}`
}

function readValue(v: unknown): string {
  if (typeof v === 'string') return v
  const target = (v as { target?: { value?: string } } | null)?.target
  return target?.value ?? ''
}

export default function PagomenScreen({ navigate }: ScreenProps) {
  const [opcion, setOpcion] = useState('')
  const [fieldError, setFieldError] = useState<string | undefined>(undefined)
  const [mensaje, setMensaje] = useState<Msg>(null)
  const fecha = today()

  const handleChange = (v: unknown) => {
    const clean = readValue(v).replace(/\D/g, '').slice(0, 1)
    setOpcion(clean)
    setFieldError(undefined)
    if (mensaje) setMensaje(null)
  }

  const onSubmit = (e: { preventDefault: () => void }) => {
    e.preventDefault()
    if (opcion.trim() === '') {
      const text = 'Debe ingresar una opción.'
      setFieldError(text)
      setMensaje({ tone: 'error', text })
      return
    }
    if (opcion !== '1' && opcion !== '2') {
      const text = 'Opción inválida. Ingrese 1 o 2.'
      setFieldError(text)
      setMensaje({ tone: 'error', text })
      return
    }
    setFieldError(undefined)
    setMensaje({ tone: 'success', text: 'Opción aceptada. Continuando...' })
    navigate('SCR-PAGOORD')
  }

  const onExit = () => {
    setOpcion('')
    setFieldError(undefined)
    setMensaje({ tone: 'info', text: 'Sesión de pagos finalizada.' })
  }

  return (
    <Screen title="BANCO FICTICIO - PAGOS">
      <form onSubmit={onSubmit} noValidate>
        <Stack>
          <div>
            <span>FECHA: </span>
            <span data-field="FECHA">{fecha}</span>
          </div>

          <Card title="Menú de pagos">
            <Stack>
              {MENU.map((item) => (
                <p key={item.value}>
                  {item.value} - {item.label}
                </p>
              ))}
            </Stack>
          </Card>

          <Card title="Selección">
            <Stack>
              <div data-field="OPCION">
                <TextField
                  label="OPCION"
                  required
                  numeric
                  maxLength={1}
                  hint="Ingrese 1 para pagar una orden o 2 para consultarla"
                  error={fieldError}
                  value={opcion}
                  onChange={handleChange}
                />
              </div>
              <div>
                <Button type="submit" variant="primary" data-action="ENTER">
                  CONTINUAR
                </Button>{' '}
                <Button type="button" variant="secondary" data-action="PF3" onClick={onExit}>
                  SALIR
                </Button>
              </div>
            </Stack>
          </Card>

          <div data-field="MENSAJE" aria-live="polite">
            {mensaje && <Alert tone={mensaje.tone}>{mensaje.text}</Alert>}
          </div>
        </Stack>
      </form>
    </Screen>
  )
}
